const [count, setCount] = useState(0)
setCount(count + 1)        // 依赖旧值，有风险
setCount(c => c + 1)       // 函数式更新，安全
const [list, setList] = useState([])
setList(prev => [...prev, '新项'])  // 不可变：新数组而非 push

const [text, setText] = useState('')
return <input
  value={text}
  onChange={e => setText(e.target.value)}
  placeholder='输入点什么' />

// 同一事件里三次 setCount(count+1)，最终只 +1（都基于同一个旧快照）
// 改用函数式则每次基于最新值，最终 +3
setCount(c => c + 1)
setCount(c => c + 1)
setCount(c => c + 1)

function App() {
  const [q, setQ] = useState('')
  return <>
    <Input value={q} onChange={setQ} />
    <Display value={q} />
  </>
}

function reducer(count, action) {
  switch (action.type) {
    case 'inc': return count + 1
    case 'dec': return count - 1
    case 'reset': return 0
    default: return count
  }
}
const [count, dispatch] = useReducer(reducer, 0)
dispatch({ type: 'inc' })
